// Helper: max-heapify subtree rooted at index 'root' for heap size 'heapSize'
auto maxHeapify = [&](int root, int heapSize) {
    int largest = root;
    int left = 2 * root + 1;
    int right = 2 * root + 2;

    if (left < heapSize && arr[left] > arr[largest])
        largest = left;
    if (right < heapSize && arr[right] > arr[largest])
        largest = right;

    if (largest != root) {
        std::swap(arr[root], arr[largest]);
        maxHeapify(largest, heapSize);
    }
};

// Build max-heap bottom-up: start from last non-leaf node down to root
for (int i = size / 2 - 1; i >= 0; --i) {
    maxHeapify(i, size);
}

